#include "h8_first_instructions.h"
#include "h8_memory_fixture.h"
#include <algorithm>
#include <cstdio>
using Cpu=yamanix::H8FirstInstructions<struct StackHost>;
struct StackHost:Host {
 std::map<uint32_t,uint16_t> code;
 uint16_t read_instruction_word(uint32_t a){if(a&1)throw std::runtime_error("odd instruction");auto v=code[a&0xffffff];trace.emplace_back('I',a,v);return v;}
 void at(uint32_t a,std::initializer_list<uint16_t> p){for(auto v:p){code[a&0xffffff]=v;a+=2;}}
 void load(unsigned r,uint32_t v,uint32_t& pc){at(pc,{uint16_t(0x7a00|r),uint16_t(v>>16),uint16_t(v)});pc+=6;}
 StackHost(){at(0,{0,0x100});}
 void word(uint32_t a,unsigned v){data[a&0xfffffe]=uint8_t(v>>8);data[(a&0xfffffe)+1]=uint8_t(v);}
};
static unsigned failures=0;
static void check(bool ok,const char* m){if(!ok && ++failures<15)std::fprintf(stderr,"%s\n",m);}
static uint32_t reg(const Cpu& c,unsigned n){auto r=c.snapshot().registers;return r[n]|(uint32_t(r[n+8])<<16);}
static unsigned count(const StackHost& h,char k){return unsigned(std::count_if(h.trace.begin(),h.trace.end(),[=](auto e){return std::get<0>(e)==k;}));}
static bool condition(unsigned op,unsigned c){bool C=c&1,V=c&2,Z=c&4,N=c&8;switch(op){case 0:return true;case 1:return false;case 2:return !C&&!Z;case 3:return C||Z;case 4:return !C;case 5:return C;case 6:return !Z;case 7:return Z;case 8:return !V;case 9:return V;case 10:return !N;case 11:return N;case 12:return N==V;case 13:return N!=V;case 14:return !Z&&N==V;default:return Z||N!=V;}}
static void stack_word(StackHost& h,uint32_t sp,uint32_t value){h.word(sp,value>>16);h.word(sp+2,value);}
int main(){
 // All branch conditions and every signed even rel16 displacement, with varying CCR.
 for(unsigned op=0;op<16;++op)for(unsigned n=0;n<32768;++n){unsigned seed=(n*37)&255;int displacement=int(int16_t(n*2));StackHost h;h.at(0x100,{uint16_t(0x0700|seed),uint16_t(0x5800|(op<<4)),uint16_t(displacement)});uint32_t target=uint32_t(0x106+displacement)&0xffffff,fall=0x106;if(target<4 || (target>=0x100&&target<=0x106))continue;h.at(target,{0x40fe});h.at(fall,{0x40fe});Cpu c(h);c.run(0,64,1000);check(c.snapshot().ppc==(condition(op,seed)?target:fall) && c.snapshot().ccr==seed && count(h,'S')==0,"rel16 condition, signed displacement, CCR");}
 for(unsigned bits:{8u,16u,32u})for(unsigned ptr=0;ptr<8;++ptr)for(unsigned lane=0;lane<(bits==32?8u:16u);++lane)for(unsigned seed=0;seed<32;++seed)for(bool store:{false,true}){
  StackHost h;uint32_t pc=0x100;std::array<uint16_t,16> want{};for(unsigned n=0;n<8;++n){uint32_t v=(0x1234567u*(n+1))^(seed*0x11111111u);if(n==ptr)v=(seed&1)?0xab123457:0;want[n]=uint16_t(v);want[n+8]=uint16_t(v>>16);h.load(n,v,pc);}uint32_t address=uint32_t(want[ptr])|(uint32_t(want[ptr+8])<<16);unsigned step=bits/8;uint32_t source=bits==8?uint8_t(lane&8?want[lane&7]:want[lane&7]/256):bits==16?want[lane]:uint32_t(want[lane])|(uint32_t(want[lane+8])<<16);uint32_t value=seed*0x1234567u;if(bits==8)value&=255;if(bits==16)value&=65535;h.data[address&0xffffff]=uint8_t(value);if(bits>=16)h.word(address,bits==16?value:value>>16);if(bits==32)h.word(address+2,value);h.at(pc,{uint16_t(0x0700|seed)});pc+=2;if(bits==32){h.at(pc,{0x0100});pc+=2;}h.at(pc,{uint16_t((bits==8?0x6c00:0x6d00)|(store?0x80:0)|(ptr<<4)|lane),0x40fe});Cpu c(h);c.run(0,128,1000);
  uint32_t updated=store?address-step:address+step;want[ptr]=uint16_t(updated);want[ptr+8]=uint16_t(updated>>16);uint32_t actualValue=store?source:value;if(!store){if(bits==8){auto& r=want[lane&7];r=uint16_t(lane&8?((r&0xff00)|value):((r&255)|(value<<8)));}else{want[lane]=uint16_t(value);if(bits==32)want[lane+8]=uint16_t(value>>16);}}
  unsigned flags=(seed&~14)|(actualValue==0?4:((uint64_t(actualValue)>>(bits-1))?8:0));check(c.snapshot().registers==want && c.snapshot().ccr==flags,"predecrement/postincrement width, alias, wrap, flags");check(count(h,store?(bits==8?'W':'S'):(bits==8?'R':'Q'))==(bits==32?2u:1u),"exact stack data access count");if(store){uint32_t a=updated&0xffffff;if(bits==8)check(h.data[a]==uint8_t(source),"byte push data");else {a&=~1u;check(h.data[a]==uint8_t(source>>(bits==16?8:24)) && h.data[(a+1)&0xffffff]==uint8_t(source>>(bits==16?0:16)),"word/high long push data");if(bits==32)check(h.data[(a+2)&0xffffff]==uint8_t(source>>8) && h.data[(a+3)&0xffffff]==uint8_t(source),"low long push data");}}
 }
 // Call targets in three addressing modes plus both BSR widths, including ER7 alias.
 for(unsigned form=0;form<5;++form)for(unsigned seed=0;seed<256;++seed){StackHost h;uint32_t pc=0x100;uint32_t sp=seed&1?0:0xab123457;h.load(7,sp,pc);h.load(2,0x180,pc);h.at(pc,{uint16_t(0x0700|seed)});pc+=2;uint32_t ret=pc+(form==1||form==4?4:2);if(form==0)h.at(pc,{0x5d20});if(form==1)h.at(pc,{0x5e00,0x180});if(form==2){h.at(pc,{0x5f40});stack_word(h,0x40,0x180);}if(form==3)h.at(pc,{uint16_t(0x5500|uint8_t(0x180-pc-2))});if(form==4)h.at(pc,{0x5c00,uint16_t(0x180-pc-4)});h.at(ret,{0x40fe});h.at(0x180,{0x5470,0});Cpu c(h);c.run(0,128,1000);check(c.snapshot().ppc==ret && reg(c,7)==sp && c.snapshot().ccr==seed,"all call forms return and restore stack/CCR");check(count(h,'S')==2 && count(h,'Q')==(form==2?4u:2u),"call/return access counts");uint32_t a=(sp-4)&0xfffffe;check(h.data[a]==0 && h.data[(a+1)&0xffffff]==0 && h.data[(a+2)&0xffffff]==uint8_t(ret>>8) && h.data[(a+3)&0xffffff]==uint8_t(ret),"advanced four-byte return frame layout");}
 for(unsigned form=0;form<3;++form)for(unsigned seed=0;seed<256;++seed){StackHost h;uint32_t pc=0x100;h.load(7,0x200,pc);h.at(pc,{uint16_t(0x0700|seed)});pc+=2;if(form==0)h.at(pc,{0x5970});if(form==1)h.at(pc,{0x5a00,0x200});if(form==2){h.at(pc,{0x5b40});stack_word(h,0x40,0x200);}h.at(0x200,{0x40fe});Cpu c(h);c.run(0,64,1000);check(c.snapshot().ppc==0x200 && reg(c,7)==0x200 && c.snapshot().ccr==seed && count(h,'S')==0,"all JMP forms preserve SP/CCR");}
 for(unsigned seed=0;seed<256;++seed){StackHost h;uint32_t pc=0x100;h.load(7,0xab123457,pc);h.at(pc,{0x5670});h.word(0x123457,(seed<<8)|0);h.word(0x123459,0x200);h.at(0x200,{0x40fe});Cpu c(h);c.run(0,64,1000);check(c.snapshot().ppc==0x200 && c.snapshot().ccr==seed && reg(c,7)==0xab12345b && count(h,'Q')==2,"RTE advanced frame CCR/PC restore without EXR");}
 for(unsigned wide=0;wide<2;++wide)for(unsigned n=0;n<(wide?32768u:128u);++n){int d=wide?int(int16_t(n*2)):int(int8_t(n*2));uint32_t call=0x106,ret=call+(wide?4:2),target=uint32_t(ret+d)&0xffffff;if(target<4 || (target>=0x100&&target<=ret+2))continue;StackHost h;h.at(0x100,{0x7a07,0xab12,0x3456});if(wide)h.at(call,{0x5c00,uint16_t(d)});else h.at(call,{uint16_t(0x5500|uint8_t(d))});h.at(ret,{0x40fe});h.at(target,{0x5470});Cpu c(h);c.run(0,128,1000);check(c.snapshot().ppc==ret && reg(c,7)==0xab123456 && count(h,'S')==2 && count(h,'Q')==2,"BSR all signed even displacements and exact return");}
 for(unsigned form=0;form<3;++form)for(uint32_t target:{0x200u,0x800000u,0xfffffcu,0xab123456u}){if(form==1 && target>0xffffff)continue;StackHost h;uint32_t pc=0x100;h.load(2,target,pc);if(form==0)h.at(pc,{0x5920});if(form==1)h.at(pc,{uint16_t(0x5a00|(target>>16)),uint16_t(target)});if(form==2){h.at(pc,{0x5bfc});stack_word(h,0xfc,target);}h.at(target,{0x40fe});Cpu c(h);c.run(0,64,1000);check(c.snapshot().ppc==(target&0xffffff),"JMP full address and advanced indirect vector page");}
 {StackHost h;h.at(0x100,{0x7a07,0,0x180,0x5d70,0x40fe});h.at(0x180,{0x5470});Cpu c(h);c.run(0,128,1000);check(c.snapshot().ppc==0x108 && reg(c,7)==0x180,"JSR ER7 reads target before predecrementing SP");}
 for(unsigned form=0;form<4;++form)for(unsigned split=0;split<=96;++split){StackHost a,b;for(auto* h:{&a,&b}){h->at(0x100,{0x7a07,0xab12,0x3456,0x7a02,0,0x200});if(form==0)h->at(0x10c,{0x5d20,0x40fe});if(form==1){h->at(0x10c,{0x5f40,0x40fe});stack_word(*h,0x40,0x200);}if(form==2)h->at(0x10c,{0x5c00,0xf0,0x40fe});if(form==3){h->at(0x10c,{0x5670});h->word(0x123456,0xa500);h->word(0x123458,0x240);}h->at(0x200,{0x5470});h->at(0x240,{0x40fe});}Cpu x(a),y(b);x.run(0,96,1000);y.run(0,int(split),1000);y.run(split,int(96-split),1000);check(x.snapshot()==y.snapshot() && a.trace==b.trace && a.data==b.data,"call/vector/BSR/RTE every cycle split");}
 for(unsigned which=0;which<3;++which){StackHost h;h.at(0x100,{0x7a07,0,0x400,0x7a02,0,0x201});if(which==0)h.at(0x10c,{0x5920});if(which==1)h.at(0x10c,{0x5d20});if(which==2){h.at(0x10c,{0x5470});stack_word(h,0x400,0x201);}Cpu c(h);bool threw=false;try{c.run(0,64,1000);}catch(const std::runtime_error&){threw=true;}check(!threw && !c.failed() && std::all_of(h.trace.begin(),h.trace.end(),[](auto e){return std::get<0>(e)!='I' || (std::get<1>(e)&1)==0;}),"odd control targets retain reviewed aligned instruction-bus reads");}
 for(bool exception:{false,true})for(uint32_t sp:{0u,0xffffffffu,0xab123457u})for(uint32_t target:{0x200u,0x800000u,0xfffffcu})for(unsigned seed=0;seed<256;++seed){StackHost h;h.at(0x100,{0x7a07,uint16_t(sp>>16),uint16_t(sp),uint16_t(0x0700|seed),uint16_t(exception?0x5670:0x5470)});if(exception){h.word(sp,(seed<<8)|(target>>16));h.word(sp+2,target);}else stack_word(h,sp,target|0xab000000);h.at(target,{0x40fe});Cpu c(h,uint8_t(seed));c.run(0,96,1000);check(c.snapshot().ppc==(target&0xffffff) && reg(c,7)==sp+4 && c.snapshot().ccr==seed,"RTS/RTE frame boundary addresses, wrap, alignment and all CCR values");}
 // Nested calls, explicit long push/pop, followed by return to a stable loop.
 for(unsigned split=0;split<=200;++split){StackHost a,b;for(auto* h:{&a,&b}){h->at(0x100,{0x7a07,0xab12,0x3456,0x7a00,0x89ab,0xcdef,0x5e00,0x200,0x40fe});h->at(0x200,{0x0100,0x6df0,0x5e00,0x240,0x0100,0x6d71,0x5470});h->at(0x240,{0x5470});}Cpu x(a),y(b);x.run(0,200,1000);y.run(0,int(split),1000);y.run(split,int(200-split),1000);check(x.snapshot()==y.snapshot() && a.trace==b.trace && a.data==b.data && reg(y,7)==0xab123456 && reg(y,1)==0x89abcdef,"nested calls and push/pop every cycle split");}
 for(unsigned fail=1;fail<=2;++fail){StackHost h;h.at(0x100,{0x7a07,0xab12,0x3456,0x5e00,0x200});h.at(0x200,{0x40fe});h.fail_word_write=fail;Cpu c(h);bool threw=false;try{c.run(0,64,1000);}catch(const std::runtime_error&){threw=true;}check(threw&&c.failed()&&count(h,'S')==fail && reg(c,7)==0xab123452,"mid-call stack write failure preserves committed SP and writes");}
 std::printf("H8 stack/control: rel16 displacement matrix, all pre/post widths and aliases, call/JMP/RTE forms, 201 nested splits: %u failures\n",failures);return failures?1:0;
}
